SELECT ?screenplayWriter ?screenplayWriterNobel ?basedOnNovel WHERE {
  ?film wdt:P31 wd:Q11424;                # ?film is a film
        rdfs:label "The Night Hunter"@en;
        wdt:P344 ?screenplayWriterID.       # film screenplay writers

  OPTIONAL {
    ?film wdt:P144 ?originalWork.          # film based on original work
    ?originalWork wdt:P31 wd:Q8261.        # original work is a novel
  }

  BIND(IF(BOUND(?originalWork), true, false) AS ?basedOnNovel)

  # Get screenplay writer details
  ?screenplayWriterID rdfs:label ?screenplayWriter.

  # Check if screenplay writer has won Nobel Prize in Literature
  OPTIONAL {
    ?screenplayWriterID wdt:P166 wd:Q37922.  # Nobel Prize in Literature
  }
  BIND(IF(BOUND(?screenplayWriterID), IF(BOUND(?screenplayWriterID) && EXISTS { ?screenplayWriterID wdt:P166 wd:Q37922 }, true, false), false) AS ?screenplayWriterNobel)

  FILTER(LANG(?screenplayWriter) = "en")
}

LIMIT 10

# Later, check if screenplayWriterNobel and Nelly Sachs Nobel Prize status (Nelly Sachs won Nobel Prize in Literature) are both true or not.

